104	//==============================================================================
105	
106	int32_t Lattice::fill_offset_table(int32_t target_univ_id, int map,
107	  std::unordered_map<int32_t, int32_t>& univ_count_memo)
108	{
109	  // If the offsets have already been determined for this "map", don't bother
110	  // recalculating all of them and just return the total offset. Note that the
111	  // offsets_ array doesn't actually include the offset accounting for the last
112	  // universe, so we get the before-last offset for the given map and then
113	  // explicitly add the count for the last universe.
114	  if (offsets_[map * universes_.size() + this->begin().indx_] != C_NONE) {
115	    int last_offset =
116	      offsets_[(map + 1) * universes_.size() - this->begin().indx_ - 1];
117	    int last_univ = this->back();
118	    return last_offset +
119	           count_universe_instances(last_univ, target_univ_id, univ_count_memo);
120	  }
121	
122	  int32_t offset = 0;
123	  for (LatticeIter it = begin(); it != end(); ++it) {
124	    offsets_[map * universes_.size() + it.indx_] = offset;
125	    offset += count_universe_instances(*it, target_univ_id, univ_count_memo);
126	  }
127	
128	  return offset;
129	}
