329	
330	Position RectLattice::get_local_position(
331	  Position r, const array<int, 3>& i_xyz) const
332	{
333	  r.x -= (lower_left_.x + (i_xyz[0] + 0.5) * pitch_.x);
334	  r.y -= (lower_left_.y + (i_xyz[1] + 0.5) * pitch_.y);
335	  if (is_3d_) {
336	    r.z -= (lower_left_.z + (i_xyz[2] + 0.5) * pitch_.z);
337	  }
338	  return r;
339	}
