378	
379	std::string RectLattice::index_to_string(int indx) const
380	{
381	  int iz {indx / (n_cells_[0] * n_cells_[1])};
382	  int iy {(indx - n_cells_[0] * n_cells_[1] * iz) / n_cells_[0]};
383	  int ix {indx - n_cells_[0] * n_cells_[1] * iz - n_cells_[0] * iy};
384	  std::string out {std::to_string(ix)};
385	  out += ',';
386	  out += std::to_string(iy);
387	  if (is_3d_) {
388	    out += ',';
389	    out += std::to_string(iz);
390	  }
391	  return out;
392	}
