724	
725	bool HexLattice::are_valid_indices(const array<int, 3>& i_xyz) const
726	{
727	  // Check if (x, alpha, z) indices are valid, accounting for number of rings
728	  return ((i_xyz[0] >= 0) && (i_xyz[1] >= 0) && (i_xyz[2] >= 0) &&
729	          (i_xyz[0] < 2 * n_rings_ - 1) && (i_xyz[1] < 2 * n_rings_ - 1) &&
730	          (i_xyz[0] + i_xyz[1] > n_rings_ - 2) &&
731	          (i_xyz[0] + i_xyz[1] < 3 * n_rings_ - 2) && (i_xyz[2] < n_axial_));
732	}
