979	//==============================================================================
980	
981	Position HexLattice::get_local_position(
982	  Position r, const array<int, 3>& i_xyz) const
983	{
984	  if (orientation_ == Orientation::y) {
985	    // x_l = x_g - (center + pitch_x*cos(30)*index_x)
986	    r.x -=
987	      center_.x + std::sqrt(3.0) / 2.0 * (i_xyz[0] - n_rings_ + 1) * pitch_[0];
988	    // y_l = y_g - (center + pitch_x*index_x + pitch_y*sin(30)*index_y)
989	    r.y -= (center_.y + (i_xyz[1] - n_rings_ + 1) * pitch_[0] +
990	            (i_xyz[0] - n_rings_ + 1) * pitch_[0] / 2.0);
991	  } else {
992	    // x_l = x_g - (center + pitch_x*index_a + pitch_y*sin(30)*index_y)
993	    r.x -= (center_.x + (i_xyz[0] - n_rings_ + 1) * pitch_[0] +
994	            (i_xyz[1] - n_rings_ + 1) * pitch_[0] / 2.0);
995	    // y_l = y_g - (center + pitch_y*cos(30)*index_y)
996	    r.y -=
997	      center_.y + std::sqrt(3.0) / 2.0 * (i_xyz[1] - n_rings_ + 1) * pitch_[0];
998	  }
999	
1000	  if (is_3d_) {
1001	    r.z -= center_.z - (0.5 * n_axial_ - i_xyz[2] - 0.5) * pitch_[1];
1002	  }
1003	
1004	  return r;
1005	}
