1093	
1094	bool HexLattice::is_valid_index(int indx) const
1095	{
1096	  int nx {2 * n_rings_ - 1};
1097	  int ny {2 * n_rings_ - 1};
1098	  int iz = indx / (nx * ny);
1099	  int iy = (indx - nx * ny * iz) / nx;
1100	  int ix = indx - nx * ny * iz - nx * iy;
1101	  array<int, 3> i_xyz {ix, iy, iz};
1102	  return are_valid_indices(i_xyz);
1103	}
