1126	std::string HexLattice::index_to_string(int indx) const
1127	{
1128	  int nx {2 * n_rings_ - 1};
1129	  int ny {2 * n_rings_ - 1};
1130	  int iz {indx / (nx * ny)};
1131	  int iy {(indx - nx * ny * iz) / nx};
1132	  int ix {indx - nx * ny * iz - nx * iy};
1133	  std::string out {std::to_string(ix - n_rings_ + 1)};
1134	  out += ',';
1135	  out += std::to_string(iy - n_rings_ + 1);
1136	  if (is_3d_) {
1137	    out += ',';
1138	    out += std::to_string(iz);
1139	  }
1140	  return out;
1141	}
