1144	
1145	void HexLattice::to_hdf5_inner(hid_t lat_group) const
1146	{
1147	  // Write basic lattice information.
1148	  write_string(lat_group, "type", "hexagonal", false);
1149	  write_dataset(lat_group, "n_rings", n_rings_);
1150	  write_dataset(lat_group, "n_axial", n_axial_);
1151	  if (orientation_ == Orientation::y) {
1152	    write_string(lat_group, "orientation", "y", false);
1153	  } else {
1154	    write_string(lat_group, "orientation", "x", false);
1155	  }
1156	  if (is_3d_) {
1157	    write_dataset(lat_group, "pitch", pitch_);
1158	    write_dataset(lat_group, "center", center_);
1159	  } else {
1160	    array<double, 1> pitch_short {{pitch_[0]}};
1161	    write_dataset(lat_group, "pitch", pitch_short);
1162	    array<double, 2> center_short {{center_[0], center_[1]}};
1163	    write_dataset(lat_group, "center", center_short);
1164	  }
1165	
1166	  // Write the universe ids.
1167	  hsize_t nx {static_cast<hsize_t>(2 * n_rings_ - 1)};
1168	  hsize_t ny {static_cast<hsize_t>(2 * n_rings_ - 1)};
1169	  hsize_t nz {static_cast<hsize_t>(n_axial_)};
1170	  vector<int> out(nx * ny * nz);
1171	
1172	  for (int m = 0; m < nz; m++) {
1173	    for (int k = 0; k < ny; k++) {
1174	      for (int j = 0; j < nx; j++) {
1175	        int indx = nx * ny * m + nx * k + j;
1176	        if (j + k < n_rings_ - 1) {
1177	          // This array position is never used; put a -1 to indicate this.
1178	          out[indx] = -1;
1179	        } else if (j + k > 3 * n_rings_ - 3) {
1180	          // This array position is never used; put a -1 to indicate this.
1181	          out[indx] = -1;
1182	        } else {
1183	          out[indx] = model::universes[universes_[indx]]->id_;
1184	        }
1185	      }
1186	    }
1187	  }
1188	
1189	  hsize_t dims[3] {nz, ny, nx};
1190	  write_int(lat_group, 3, dims, "universes", out.data(), false);
1191	}
