90	
91	void adjust_indices()
92	{
93	  // Adjust material/fill idices.
94	  for (auto& c : model::cells) {
95	    if (c->fill_ != C_NONE) {
96	      int32_t id = c->fill_;
97	      auto search_univ = model::universe_map.find(id);
98	      auto search_lat = model::lattice_map.find(id);
99	      if (search_univ != model::universe_map.end()) {
100	        c->type_ = Fill::UNIVERSE;
101	        c->fill_ = search_univ->second;
102	      } else if (search_lat != model::lattice_map.end()) {
103	        c->type_ = Fill::LATTICE;
104	        c->fill_ = search_lat->second;
105	      } else {
106	        fatal_error(fmt::format("Specified fill {} on cell {} is neither a "
107	                                "universe nor a lattice.",
108	          id, c->id_));
109	      }
110	    } else {
111	      c->type_ = Fill::MATERIAL;
112	      for (auto& mat_id : c->material_) {
113	        if (mat_id != MATERIAL_VOID) {
114	          auto search = model::material_map.find(mat_id);
115	          if (search == model::material_map.end()) {
116	            fatal_error(
117	              fmt::format("Could not find material {} specified on cell {}",
118	                mat_id, c->id_));
119	          }
120	          // Change from ID to index
121	          mat_id = search->second;
122	        }
123	      }
124	    }
125	  }
126	
127	  // Change cell.universe values from IDs to indices.
128	  for (auto& c : model::cells) {
129	    auto search = model::universe_map.find(c->universe_);
130	    if (search != model::universe_map.end()) {
131	      c->universe_ = search->second;
132	    } else {
133	      fatal_error(fmt::format("Could not find universe {} specified on cell {}",
134	        c->universe_, c->id_));
135	    }
136	  }
137	
138	  // Change all lattice universe values from IDs to indices.
139	  for (auto& l : model::lattices) {
140	    l->adjust_indices();
141	  }
142	}
