144	//==============================================================================
145	//! Partition some universes with many z-planes for faster find_cell searches.
146	
147	void partition_universes()
148	{
149	  // Iterate over universes with more than 10 cells.  (Fewer than 10 is likely
150	  // not worth partitioning.)
151	  for (const auto& univ : model::universes) {
152	    if (univ->cells_.size() > 10) {
153	      // Collect the set of surfaces in this universe.
154	      std::unordered_set<int32_t> surf_inds;
155	      for (auto i_cell : univ->cells_) {
156	        for (auto token : model::cells[i_cell]->surfaces()) {
157	          surf_inds.insert(std::abs(token) - 1);
158	        }
159	      }
160	
161	      // Partition the universe if there are more than 5 z-planes.  (Fewer than
162	      // 5 is likely not worth it.)
163	      int n_zplanes = 0;
164	      for (auto i_surf : surf_inds) {
165	        if (dynamic_cast<const SurfaceZPlane*>(model::surfaces[i_surf].get())) {
166	          ++n_zplanes;
167	          if (n_zplanes > 5) {
168	            univ->partitioner_ = make_unique<UniversePartitioner>(*univ);
169	            break;
170	          }
171	        }
172	      }
173	    }
174	  }
175	}
