203	void finalize_cell_densities()
204	{
205	  for (auto& c : model::cells) {
206	    // Convert to density multipliers.
207	    if (!c->density_mult_.empty()) {
208	      for (int32_t instance = 0; instance < c->density_mult_.size();
209	           ++instance) {
210	        c->density_mult_[instance] /=
211	          model::materials[c->material(instance)]->density_gpcc();
212	      }
213	    } else {
214	      c->density_mult_ = {1.0};
215	    }
216	  }
