331	
332	void prepare_distribcell(const std::vector<int32_t>* user_distribcells)
333	{
334	  write_message("Preparing distributed cell instances...", 5);
335	
336	  std::unordered_set<int32_t> distribcells;
337	
338	  // start with any cells manually specified via the C++ API
339	  if (user_distribcells) {
340	    distribcells.insert(user_distribcells->begin(), user_distribcells->end());
341	  }
342	
343	  // Find all cells listed in a DistribcellFilter or CellInstanceFilter
344	  for (auto& filt : model::tally_filters) {
345	    auto* distrib_filt = dynamic_cast<DistribcellFilter*>(filt.get());
346	    auto* cell_inst_filt = dynamic_cast<CellInstanceFilter*>(filt.get());
347	    if (distrib_filt) {
348	      distribcells.insert(distrib_filt->cell());
349	    }
350	    if (cell_inst_filt) {
351	      const auto& filter_cells = cell_inst_filt->cells();
352	      distribcells.insert(filter_cells.begin(), filter_cells.end());
353	    }
354	  }
355	
356	  // By default, add material cells to the list of distributed cells
357	  if (settings::material_cell_offsets) {
358	    for (int64_t i = 0; i < model::cells.size(); ++i) {
359	      if (model::cells[i]->type_ == Fill::MATERIAL)
360	        distribcells.insert(i);
361	    }
362	  }
363	
364	  // Make sure that the number of materials/temperatures matches the number of
365	  // cell instances.
366	  for (int i = 0; i < model::cells.size(); i++) {
367	    Cell& c {*model::cells[i]};
368	
369	    if (c.material_.size() > 1) {
370	      if (c.material_.size() != c.n_instances()) {
371	        fatal_error(fmt::format(
372	          "Cell {} was specified with {} materials but has {} distributed "
373	          "instances. The number of materials must equal one or the number "
374	          "of instances.",
375	          c.id_, c.material_.size(), c.n_instances()));
376	      }
377	    }
378	
379	    if (c.sqrtkT_.size() > 1) {
380	      if (c.sqrtkT_.size() != c.n_instances()) {
381	        fatal_error(fmt::format(
382	          "Cell {} was specified with {} temperatures but has {} distributed "
383	          "instances. The number of temperatures must equal one or the number "
384	          "of instances.",
385	          c.id_, c.sqrtkT_.size(), c.n_instances()));
386	      }
387	    }
388	
389	    if (c.density_mult_.size() > 1) {
390	      if (c.density_mult_.size() != c.n_instances()) {
391	        fatal_error(fmt::format("Cell {} was specified with {} density "
392	                                "multipliers but has {} distributed "
393	                                "instances. The number of density multipliers "
394	                                "must equal one or the number "
395	                                "of instances.",
396	          c.id_, c.density_mult_.size(), c.n_instances()));
397	      }
398	    }
399	  }
400	
401	  // Search through universes for material cells and assign each one a
402	  // distribcell array index according to the containing universe.
403	  vector<int32_t> target_univ_ids;
404	  for (const auto& u : model::universes) {
405	    for (auto idx : u->cells_) {
406	      if (distribcells.find(idx) != distribcells.end()) {
407	        if (!contains(target_univ_ids, u->id_)) {
408	          target_univ_ids.push_back(u->id_);
409	        }
410	        model::cells[idx]->distribcell_index_ =
411	          std::find(target_univ_ids.begin(), target_univ_ids.end(), u->id_) -
412	          target_univ_ids.begin();
413	      }
414	    }
415	  }
416	
417	  // Allocate the cell and lattice offset tables.
418	  int n_maps = target_univ_ids.size();
419	  for (auto& c : model::cells) {
420	    if (c->type_ != Fill::MATERIAL) {
421	      c->offset_.resize(n_maps, C_NONE);
422	    }
423	  }
424	  for (auto& lat : model::lattices) {
425	    lat->allocate_offset_table(n_maps);
426	  }
427	
428	// Fill the cell and lattice offset tables.
429	#pragma omp parallel for
430	  for (int map = 0; map < target_univ_ids.size(); map++) {
431	    auto target_univ_id = target_univ_ids[map];
432	    std::unordered_map<int32_t, int32_t> univ_count_memo;
433	    for (const auto& univ : model::universes) {
434	      int32_t offset = 0;
435	      for (int32_t cell_indx : univ->cells_) {
436	        Cell& c = *model::cells[cell_indx];
437	
438	        if (c.type_ == Fill::UNIVERSE) {
439	          c.offset_[map] = offset;
440	          int32_t search_univ = c.fill_;
441	          offset += count_universe_instances(
442	            search_univ, target_univ_id, univ_count_memo);
443	
444	        } else if (c.type_ == Fill::LATTICE) {
445	          c.offset_[map] = offset;
446	          Lattice& lat = *model::lattices[c.fill_];
447	          offset += lat.fill_offset_table(target_univ_id, map, univ_count_memo);
448	        }
449	      }
450	    }
451	  }
452	}
