456	void count_universe_instances()
457	{
458	  for (auto& univ : model::universes) {
459	    std::unordered_map<int32_t, int32_t> univ_count_memo;
460	    univ->n_instances_ = count_universe_instances(
461	      model::root_universe, univ->id_, univ_count_memo);
