465	//==============================================================================
466	
467	int count_universe_instances(int32_t search_univ, int32_t target_univ_id,
468	  std::unordered_map<int32_t, int32_t>& univ_count_memo)
469	{
470	  // If this is the target, it can't contain itself.
471	  if (model::universes[search_univ]->id_ == target_univ_id) {
472	    return 1;
473	  }
474	
475	  // If we have already counted the number of instances, reuse that value.
476	  auto search = univ_count_memo.find(search_univ);
477	  if (search != univ_count_memo.end()) {
478	    return search->second;
479	  }
480	
481	  int count {0};
482	  for (int32_t cell_indx : model::universes[search_univ]->cells_) {
483	    Cell& c = *model::cells[cell_indx];
484	
485	    if (c.type_ == Fill::UNIVERSE) {
486	      int32_t next_univ = c.fill_;
487	      count +=
488	        count_universe_instances(next_univ, target_univ_id, univ_count_memo);
489	
490	    } else if (c.type_ == Fill::LATTICE) {
491	      Lattice& lat = *model::lattices[c.fill_];
492	      for (auto it = lat.begin(); it != lat.end(); ++it) {
493	        int32_t next_univ = *it;
494	        count +=
495	          count_universe_instances(next_univ, target_univ_id, univ_count_memo);
496	      }
497	    }
498	  }
499	
500	  // Remember the number of instances in this universe.
501	  univ_count_memo[search_univ] = count;
502	
503	  return count;
504	}
