595	
596	int maximum_levels(int32_t univ)
597	{
598	
599	  const auto level_count = model::universe_level_counts.find(univ);
600	  if (level_count != model::universe_level_counts.end()) {
601	    return level_count->second;
602	  }
603	
604	  int levels_below {0};
605	
606	  for (int32_t cell_indx : model::universes[univ]->cells_) {
607	    Cell& c = *model::cells[cell_indx];
608	    if (c.type_ == Fill::UNIVERSE) {
609	      int32_t next_univ = c.fill_;
610	      levels_below = std::max(levels_below, maximum_levels(next_univ));
611	    } else if (c.type_ == Fill::LATTICE) {
612	      Lattice& lat = *model::lattices[c.fill_];
613	      for (auto it = lat.begin(); it != lat.end(); ++it) {
614	        int32_t next_univ = *it;
615	        levels_below = std::max(levels_below, maximum_levels(next_univ));
616	      }
617	    }
618	  }
619	
620	  ++levels_below;
621	  model::universe_level_counts[univ] = levels_below;
622	  return levels_below;
623	}
