1140	
1141	void read_cells(pugi::xml_node node)
1142	{
1143	  // Count the number of cells.
1144	  int n_cells = 0;
1145	  for (pugi::xml_node cell_node : node.children("cell")) {
1146	    n_cells++;
1147	  }
1148	
1149	  // Loop over XML cell elements and populate the array.
1150	  model::cells.reserve(n_cells);
1151	  for (pugi::xml_node cell_node : node.children("cell")) {
1152	    model::cells.push_back(make_unique<CSGCell>(cell_node));
1153	  }
1154	
1155	  // Fill the cell map.
1156	  for (int i = 0; i < model::cells.size(); i++) {
1157	    int32_t id = model::cells[i]->id_;
1158	    auto search = model::cell_map.find(id);
1159	    if (search == model::cell_map.end()) {
1160	      model::cell_map[id] = i;
1161	    } else {
1162	      fatal_error(
1163	        fmt::format("Two or more cells use the same unique ID: {}", id));
1164	    }
1165	  }
1166	
1167	  read_dagmc_universes(node);
1168	
1169	  populate_universes();
1170	
1171	  // Allocate the cell overlap count if necessary.
1172	  if (settings::check_overlaps) {
1173	    model::overlap_check_count.resize(model::cells.size(), 0);
1174	  }
1175	
1176	  if (model::cells.size() == 0) {
1177	    fatal_error("No cells were found in the geometry.xml file");
1178	  }
1179	}
1180	
1181	void populate_universes()
1182	{
1183	  // Used to map universe index to the index of an implicit complement cell for
1184	  // DAGMC universes
1185	  std::unordered_map<int, int> implicit_comp_cells;
1186	
1187	  // Populate the Universe vector and map.
1188	  for (int index_cell = 0; index_cell < model::cells.size(); index_cell++) {
1189	    int32_t uid = model::cells[index_cell]->universe_;
1190	    auto it = model::universe_map.find(uid);
1191	    if (it == model::universe_map.end()) {
1192	      model::universes.push_back(make_unique<Universe>());
1193	      model::universes.back()->id_ = uid;
1194	      model::universes.back()->cells_.push_back(index_cell);
1195	      model::universe_map[uid] = model::universes.size() - 1;
1196	    } else {
1197	#ifdef OPENMC_DAGMC_ENABLED
1198	      // Skip implicit complement cells for now
1199	      Universe* univ = model::universes[it->second].get();
1200	      DAGUniverse* dag_univ = dynamic_cast<DAGUniverse*>(univ);
1201	      if (dag_univ && (dag_univ->implicit_complement_idx() == index_cell)) {
1202	        implicit_comp_cells[it->second] = index_cell;
1203	        continue;
1204	      }
1205	#endif
1206	
1207	      model::universes[it->second]->cells_.push_back(index_cell);
1208	    }
1209	  }
1210	
1211	  // Add DAGUniverse implicit complement cells last
1212	  for (const auto& it : implicit_comp_cells) {
1213	    int index_univ = it.first;
1214	    int index_cell = it.second;
1215	    model::universes[index_univ]->cells_.push_back(index_cell);
1216	  }
1217	
1218	  model::universes.shrink_to_fit();
