1411	//==============================================================================
1412	//! Define a containing (parent) cell
1413	//==============================================================================
1414	
1415	//! Used to locate a universe fill in the geometry
1416	struct ParentCell {
1417	  bool operator==(const ParentCell& other) const
1418	  {
1419	    return cell_index == other.cell_index &&
1420	           lattice_index == other.lattice_index;
1421	  }
1422	
1423	  bool operator<(const ParentCell& other) const
1424	  {
1425	    return cell_index < other.cell_index ||
1426	           (cell_index == other.cell_index &&
1427	             lattice_index < other.lattice_index);
1428	  }
1429	
1430	  int64_t cell_index;
1431	  int64_t lattice_index;
1432	};
1433	
1434	//! Structure used to insert ParentCell into hashed STL data structures
1435	struct ParentCellHash {
1436	  std::size_t operator()(const ParentCell& p) const
1437	  {
1438	    return 4096 * p.cell_index + p.lattice_index;
1439	  }
1440	};
1441	
1442	//! Used to manage a traversal stack when locating parent cells of a cell
1443	//! instance in the model
1444	struct ParentCellStack {
1445	
1446	  //! push method that adds to the parent_cells visited cells for this search
1447	  //! universe
1448	  void push(int32_t search_universe, const ParentCell& pc)
1449	  {
1450	    parent_cells_.push_back(pc);
1451	    // add parent cell to the set of cells we've visited for this search
1452	    // universe
1453	    visited_cells_[search_universe].insert(pc);
1454	  }
1455	
1456	  //! removes the last parent_cell and clears the visited cells for the popped
1457	  //! cell's universe
1458	  void pop()
1459	  {
1460	    visited_cells_[this->current_univ()].clear();
1461	    parent_cells_.pop_back();
1462	  }
1463	
1464	  //! checks whether or not the parent cell has been visited already for this
1465	  //! search universe
1466	  bool visited(int32_t search_universe, const ParentCell& parent_cell)
1467	  {
1468	    return visited_cells_[search_universe].count(parent_cell) != 0;
1469	  }
1470	
1471	  //! return the next universe to search for a parent cell
1472	  int32_t current_univ() const
1473	  {
1474	    return model::cells[parent_cells_.back().cell_index]->universe_;
1475	  }
1476	
1477	  //! indicates whether nor not parent cells are present on the stack
1478	  bool empty() const { return parent_cells_.empty(); }
1479	
1480	  //! compute an instance for the provided distribcell index
1481	  int32_t compute_instance(int32_t distribcell_index) const
1482	  {
1483	    if (distribcell_index == C_NONE)
1484	      return 0;
1485	
1486	    int32_t instance = 0;
1487	    for (const auto& parent_cell : this->parent_cells_) {
1488	      auto& cell = model::cells[parent_cell.cell_index];
1489	      if (cell->type_ == Fill::UNIVERSE) {
1490	        instance += cell->offset_[distribcell_index];
1491	      } else if (cell->type_ == Fill::LATTICE) {
1492	        auto& lattice = model::lattices[cell->fill_];
1493	        instance +=
1494	          lattice->offset(distribcell_index, parent_cell.lattice_index);
1495	      }
1496	    }
1497	    return instance;
1498	  }
1499	
1500	  // Accessors
1501	  vector<ParentCell>& parent_cells() { return parent_cells_; }
1502	  const vector<ParentCell>& parent_cells() const { return parent_cells_; }
1503	
1504	  // Data Members
1505	  vector<ParentCell> parent_cells_;
1506	  std::unordered_map<int32_t, std::unordered_set<ParentCell, ParentCellHash>>
1507	    visited_cells_;
1508	};
1509	
1510	vector<ParentCell> Cell::find_parent_cells(
1511	  int32_t instance, const Position& r) const
1512	{
1513	
1514	  // create a temporary particle
1515	  GeometryState dummy_particle {};
1516	  dummy_particle.r() = r;
1517	  dummy_particle.u() = {0., 0., 1.};
1518	
1519	  return find_parent_cells(instance, dummy_particle);
1520	}
1521	
1522	vector<ParentCell> Cell::find_parent_cells(
1523	  int32_t instance, GeometryState& p) const
1524	{
1525	  // look up the particle's location
1526	  exhaustive_find_cell(p);
1527	  const auto& coords = p.coord();
1528	
1529	  // build a parent cell stack from the particle coordinates
1530	  ParentCellStack stack;
1531	  bool cell_found = false;
1532	  for (auto it = coords.begin(); it != coords.end(); it++) {
1533	    const auto& coord = *it;
1534	    const auto& cell = model::cells[coord.cell()];
1535	    // if the cell at this level matches the current cell, stop adding to the
1536	    // stack
1537	    if (coord.cell() == model::cell_map[this->id_]) {
1538	      cell_found = true;
1539	      break;
1540	    }
1541	
1542	    // if filled with a lattice, get the lattice index from the next
1543	    // level in the coordinates to push to the stack
1544	    int lattice_idx = C_NONE;
1545	    if (cell->type_ == Fill::LATTICE) {
1546	      const auto& next_coord = *(it + 1);
1547	      lattice_idx = model::lattices[next_coord.lattice()]->get_flat_index(
1548	        next_coord.lattice_index());
1549	    }
1550	    stack.push(coord.universe(), {coord.cell(), lattice_idx});
1551	  }
1552	
1553	  // if this loop finished because the cell was found and
1554	  // the instance matches the one requested in the call
1555	  // we have the correct path and can return the stack
1556	  if (cell_found &&
1557	      stack.compute_instance(this->distribcell_index_) == instance) {
1558	    return stack.parent_cells();
1559	  }
1560	
1561	  // fall back on an exhaustive search for the cell's parents
1562	  return exhaustive_find_parent_cells(instance);
1563	}
1564	
1565	vector<ParentCell> Cell::exhaustive_find_parent_cells(int32_t instance) const
1566	{
1567	  ParentCellStack stack;
1568	  // start with this cell's universe
1569	  int32_t prev_univ_idx;
1570	  int32_t univ_idx = this->universe_;
1571	
1572	  while (true) {
1573	    const auto& univ = model::universes[univ_idx];
1574	    prev_univ_idx = univ_idx;
1575	
1576	    // search for a cell that is filled w/ this universe
1577	    for (const auto& cell : model::cells) {
1578	      // if this is a material-filled cell, move on
1579	      if (cell->type_ == Fill::MATERIAL)
1580	        continue;
1581	
1582	      if (cell->type_ == Fill::UNIVERSE) {
1583	        // if this is in the set of cells previously visited for this universe,
1584	        // move on
1585	        if (stack.visited(univ_idx, {model::cell_map[cell->id_], C_NONE}))
1586	          continue;
1587	
1588	        // if this cell contains the universe we're searching for, add it to the
1589	        // stack
1590	        if (cell->fill_ == univ_idx) {
1591	          stack.push(univ_idx, {model::cell_map[cell->id_], C_NONE});
1592	          univ_idx = cell->universe_;
1593	        }
1594	      } else if (cell->type_ == Fill::LATTICE) {
1595	        // retrieve the lattice and lattice universes
1596	        const auto& lattice = model::lattices[cell->fill_];
1597	        const auto& lattice_univs = lattice->universes_;
1598	
1599	        // start search for universe
1600	        auto lat_it = lattice_univs.begin();
1601	        while (true) {
1602	          // find the next lattice cell with this universe
1603	          lat_it = std::find(lat_it, lattice_univs.end(), univ_idx);
1604	          if (lat_it == lattice_univs.end())
1605	            break;
1606	
1607	          int lattice_idx = lat_it - lattice_univs.begin();
1608	
1609	          // move iterator forward one to avoid finding the same entry
1610	          lat_it++;
1611	          if (stack.visited(
1612	                univ_idx, {model::cell_map[cell->id_], lattice_idx}))
1613	            continue;
1614	
1615	          // add this cell and lattice index to the stack and exit loop
1616	          stack.push(univ_idx, {model::cell_map[cell->id_], lattice_idx});
1617	          univ_idx = cell->universe_;
1618	          break;
1619	        }
1620	      }
1621	      // if we've updated the universe, break
1622	      if (prev_univ_idx != univ_idx)
1623	        break;
1624	    } // end cell loop search for universe
1625	
1626	    // if we're at the top of the geometry and the instance matches, we're done
1627	    if (univ_idx == model::root_universe &&
1628	        stack.compute_instance(this->distribcell_index_) == instance)
1629	      break;
1630	
1631	    // if there is no match on the original cell's universe, report an error
1632	    if (univ_idx == this->universe_) {
1633	      fatal_error(
1634	        fmt::format("Could not find the parent cells for cell {}, instance {}.",
1635	          this->id_, instance));
1636	    }
1637	
1638	    // if we don't find a suitable update, adjust the stack and continue
1639	    if (univ_idx == model::root_universe || univ_idx == prev_univ_idx) {
1640	      stack.pop();
1641	      univ_idx = stack.empty() ? this->universe_ : stack.current_univ();
1642	    }
1643	
1644	  } // end while
1645	
1646	  // reverse the stack so the highest cell comes first
1647	  std::reverse(stack.parent_cells().begin(), stack.parent_cells().end());
1648	  return stack.parent_cells();
1649	}
1650	
1651	std::unordered_map<int32_t, vector<int32_t>> Cell::get_contained_cells(
1652	  int32_t instance, Position* hint) const
1653	{
1654	  std::unordered_map<int32_t, vector<int32_t>> contained_cells;
1655	
1656	  // if this is a material-filled cell it has no contained cells
1657	  if (this->type_ == Fill::MATERIAL)
1658	    return contained_cells;
1659	
1660	  // find the pathway through the geometry to this cell
1661	  vector<ParentCell> parent_cells;
1662	
1663	  // if a positional hint is provided, attempt to do a fast lookup
1664	  // of the parent cells
1665	  parent_cells = hint ? find_parent_cells(instance, *hint)
1666	                      : exhaustive_find_parent_cells(instance);
1667	
1668	  // if this cell is filled w/ a material, it contains no other cells
1669	  if (type_ != Fill::MATERIAL) {
1670	    this->get_contained_cells_inner(contained_cells, parent_cells);
1671	  }
1672	
1673	  return contained_cells;
1674	}
1675	
1676	//! Get all cells within this cell
1677	void Cell::get_contained_cells_inner(
1678	  std::unordered_map<int32_t, vector<int32_t>>& contained_cells,
1679	  vector<ParentCell>& parent_cells) const
1680	{
1681	
1682	  // filled by material, determine instance based on parent cells
1683	  if (type_ == Fill::MATERIAL) {
1684	    int instance = 0;
1685	    if (this->distribcell_index_ >= 0) {
1686	      for (auto& parent_cell : parent_cells) {
1687	        auto& cell = model::cells[parent_cell.cell_index];
1688	        if (cell->type_ == Fill::UNIVERSE) {
1689	          instance += cell->offset_[distribcell_index_];
1690	        } else if (cell->type_ == Fill::LATTICE) {
1691	          auto& lattice = model::lattices[cell->fill_];
1692	          instance += lattice->offset(
1693	            this->distribcell_index_, parent_cell.lattice_index);
1694	        }
1695	      }
1696	    }
1697	    // add entry to contained cells
1698	    contained_cells[model::cell_map[id_]].push_back(instance);
1699	    // filled with universe, add the containing cell to the parent cells
1700	    // and recurse
1701	  } else if (type_ == Fill::UNIVERSE) {
1702	    parent_cells.push_back({model::cell_map[id_], -1});
1703	    auto& univ = model::universes[fill_];
1704	    for (auto cell_index : univ->cells_) {
1705	      auto& cell = model::cells[cell_index];
1706	      cell->get_contained_cells_inner(contained_cells, parent_cells);
1707	    }
1708	    parent_cells.pop_back();
1709	    // filled with a lattice, visit each universe in the lattice
1710	    // with a recursive call to collect the cell instances
1711	  } else if (type_ == Fill::LATTICE) {
1712	    auto& lattice = model::lattices[fill_];
1713	    for (auto i = lattice->begin(); i != lattice->end(); ++i) {
1714	      auto& univ = model::universes[*i];
1715	      parent_cells.push_back({model::cell_map[id_], i.indx_});
1716	      for (auto cell_index : univ->cells_) {
1717	        auto& cell = model::cells[cell_index];
1718	        cell->get_contained_cells_inner(contained_cells, parent_cells);
1719	      }
1720	      parent_cells.pop_back();
1721	    }
1722	  }
1723	}
