66	int cell_instance_at_level(const GeometryState& p, int level)
67	{
68	  // throw error if the requested level is too deep for the geometry
69	  if (level > model::n_coord_levels) {
70	    fatal_error(fmt::format("Cell instance at level {} requested, but only {} "
71	                            "levels exist in the geometry.",
72	      level, p.n_coord()));
73	  }
74	
75	  // determine the cell instance
76	  Cell& c {*model::cells[p.coord(level).cell()]};
77	
78	  // quick exit if this cell doesn't have distribcell instances
79	  if (c.distribcell_index_ == C_NONE)
80	    return C_NONE;
81	
82	  // compute the cell's instance
83	  int instance = 0;
84	  for (int i = 0; i < level; i++) {
85	    const auto& c_i {*model::cells[p.coord(i).cell()]};
86	    if (c_i.type_ == Fill::UNIVERSE) {
87	      instance += c_i.offset_[c.distribcell_index_];
88	    } else if (c_i.type_ == Fill::LATTICE) {
89	      instance += c_i.offset_[c.distribcell_index_];
90	      auto& lat {*model::lattices[p.coord(i + 1).lattice()]};
91	      const auto& i_xyz {p.coord(i + 1).lattice_index()};
92	      if (lat.are_valid_indices(i_xyz)) {
93	        instance += lat.offset(c.distribcell_index_, i_xyz);
94	      }
95	    }
96	  }
97	  return instance;
98	}
