300	
301	void cross_lattice(GeometryState& p, const BoundaryInfo& boundary, bool verbose)
302	{
303	  auto& coord {p.lowest_coord()};
304	  auto& lat {*model::lattices[coord.lattice()]};
305	
306	  if (verbose) {
307	    write_message(
308	      fmt::format("    Crossing lattice {}. Current position ({},{},{}). r={}",
309	        lat.id_, coord.lattice_index()[0], coord.lattice_index()[1],
310	        coord.lattice_index()[2], p.r()),
311	      1);
312	  }
313	
314	  // Set the lattice indices.
315	  coord.lattice_index()[0] += boundary.lattice_translation()[0];
316	  coord.lattice_index()[1] += boundary.lattice_translation()[1];
317	  coord.lattice_index()[2] += boundary.lattice_translation()[2];
318	
319	  // Set the new coordinate position.
320	  const auto& upper_coord {p.coord(p.n_coord() - 2)};
321	  const auto& cell {model::cells[upper_coord.cell()]};
322	  Position r = upper_coord.r();
323	  r -= cell->translation_;
324	  if (!cell->rotation_.empty()) {
325	    r = r.rotate(cell->rotation_);
326	  }
327	  p.r_local() = lat.get_local_position(r, coord.lattice_index());
328	
329	  if (!lat.are_valid_indices(coord.lattice_index())) {
330	    // The particle is outside the lattice.  Search for it from the base coords.
331	    p.n_coord() = 1;
332	    bool found = exhaustive_find_cell(p);
333	
334	    if (!found) {
335	      p.mark_as_lost(fmt::format("Particle {} could not be located after "
336	                                 "crossing a boundary of lattice {}",
337	        p.id(), lat.id_));
338	    }
339	
340	  } else {
341	    // Find cell in next lattice element.
342	    p.lowest_coord().universe() = lat[coord.lattice_index()];
343	    bool found = exhaustive_find_cell(p);
344	
345	    if (!found) {
346	      // A particle crossing the corner of a lattice tile may not be found.  In
347	      // this case, search for it from the base coords.
348	      p.n_coord() = 1;
349	      bool found = exhaustive_find_cell(p);
350	      if (!found) {
351	        p.mark_as_lost(fmt::format("Particle {} could not be located after "
352	                                   "crossing a boundary of lattice {}",
353	          p.id(), lat.id_));
354	      }
355	    }
356	  }
357	}
