459	extern "C" int openmc_find_cell(
460	  const double* xyz, int32_t* index, int32_t* instance)
461	{
462	  GeometryState geom_state;
463	
464	  geom_state.r() = Position {xyz};
465	  geom_state.u() = {0.0, 0.0, 1.0};
466	
467	  if (!exhaustive_find_cell(geom_state)) {
468	    set_errmsg(
469	      fmt::format("Could not find cell at position {}.", geom_state.r()));
470	    return OPENMC_E_GEOMETRY;
471	  }
472	
473	  *index = geom_state.lowest_coord().cell();
474	  *instance = geom_state.cell_instance();
475	  return 0;
476	}
