478	extern "C" int openmc_global_bounding_box(double* llc, double* urc)
479	{
480	  auto bbox = model::universes.at(model::root_universe)->bounding_box();
481	
482	  // set lower left corner values
483	  llc[0] = bbox.min.x;
484	  llc[1] = bbox.min.y;
485	  llc[2] = bbox.min.z;
486	
487	  // set upper right corner values
488	  urc[0] = bbox.max.x;
489	  urc[1] = bbox.max.y;
490	  urc[2] = bbox.max.z;
491	
492	  return 0;
493	}
