47	double Particle::speed() const
48	{
49	  if (settings::run_CE) {
50	    // Determine mass in eV/c^2
51	    double mass = this->mass();
52	
53	    // Equivalent to C * sqrt(1-(m/(m+E))^2) without problem at E<<m:
54	    return C_LIGHT * std::sqrt(this->E() * (this->E() + 2 * mass)) /
55	           (this->E() + mass);
56	  } else {
57	    auto mat = this->material();
58	    if (mat == MATERIAL_VOID)
59	      return 1.0 / data::mg.default_inverse_velocity_[this->g()];
60	    auto& macro_xs = data::mg.macro_xs_[mat];
61	    int macro_t = this->mg_xs_cache().t;
62	    int macro_a = macro_xs.get_angle_index(this->u());
63	    return 1.0 / macro_xs.get_xs(
64	                   MgxsType::INVERSE_VELOCITY, this->g(), macro_t, macro_a);
65	  }
66	}
