68	double Particle::mass() const
69	{
70	  switch (type().pdg_number()) {
71	  case PDG_NEUTRON:
72	    return MASS_NEUTRON_EV;
73	  case PDG_ELECTRON:
74	  case PDG_POSITRON:
75	    return MASS_ELECTRON_EV;
76	  default:
77	    return this->type().mass() * AMU_EV;
78	  }
79	}
