81	bool Particle::create_secondary(
82	  double wgt, Direction u, double E, ParticleType type)
83	{
84	  // If energy is below cutoff for this particle, don't create secondary
85	  // particle
86	  int idx = type.transport_index();
87	  if (idx == C_NONE) {
88	    return false;
89	  }
90	  if (E < settings::energy_cutoff[idx]) {
91	    return false;
92	  }
93	
94	  // Increment number of secondaries created (for ParticleProductionFilter)
95	  n_secondaries()++;
96	
97	  SourceSite bank;
98	  bank.particle = type;
99	  bank.wgt = wgt;
100	  bank.r = r();
101	  bank.u = u;
102	  bank.E = settings::run_CE ? E : g();
103	  bank.time = time();
104	  bank_second_E() += bank.E;
105	  bank.parent_id = current_work();
106	  if (settings::use_shared_secondary_bank) {
107	    bank.progeny_id = n_progeny()++;
108	  }
109	  bank.wgt_born = wgt_born();
110	  bank.wgt_ww_born = wgt_ww_born();
111	  bank.n_split = n_split();
112	
113	  local_secondary_bank().emplace_back(bank);
114	  return true;
115	}
