117	void Particle::split(double wgt)
118	{
119	  SourceSite bank;
120	  bank.particle = type();
121	  bank.wgt = wgt;
122	  bank.r = r();
123	  bank.u = u();
124	  bank.E = settings::run_CE ? E() : g();
125	  bank.time = time();
126	
127	  // Convert signed index to a signed surface ID
128	  if (surface() == SURFACE_NONE) {
129	    bank.surf_id = SURFACE_NONE;
130	  } else {
131	    int surf_id = model::surfaces[surface_index()]->id_;
132	    bank.surf_id = (surface() > 0) ? surf_id : -surf_id;
133	  }
134	
135	  bank.wgt_born = wgt_born();
136	  bank.wgt_ww_born = wgt_ww_born();
137	  bank.n_split = n_split();
138	  bank.parent_id = current_work();
139	  if (settings::use_shared_secondary_bank) {
140	    bank.progeny_id = n_progeny()++;
141	  }
142	
143	  local_secondary_bank().emplace_back(bank);
144	}
