146	void Particle::from_source(const SourceSite* src)
147	{
148	  // Reset some attributes
149	  clear();
150	  surface() = SURFACE_NONE;
151	  cell_born() = C_NONE;
152	  material() = C_NONE;
153	  n_collision() = 0;
154	  fission() = false;
155	  zero_flux_derivs();
156	  lifetime() = 0.0;
157	#ifdef OPENMC_DAGMC_ENABLED
158	  history().reset();
159	#endif
160	
161	  // Copy attributes from source bank site
162	  type() = src->particle;
163	  wgt() = src->wgt;
164	  wgt_last() = src->wgt;
165	  r() = src->r;
166	  u() = src->u;
167	  r_born() = src->r;
168	  r_last_current() = src->r;
169	  r_last() = src->r;
170	  u_last() = src->u;
171	  if (settings::run_CE) {
172	    E() = src->E;
173	    g() = 0;
174	  } else {
175	    g() = static_cast<int>(src->E);
176	    g_last() = static_cast<int>(src->E);
177	    E() = data::mg.energy_bin_avg_[g()];
178	  }
179	  E_last() = E();
180	  time() = src->time;
181	  time_last() = src->time;
182	  parent_nuclide() = src->parent_nuclide;
183	  delayed_group() = src->delayed_group;
184	
185	  // Convert signed surface ID to signed index
186	  if (src->surf_id != SURFACE_NONE) {
187	    int index_plus_one = model::surface_map[std::abs(src->surf_id)] + 1;
188	    surface() = (src->surf_id > 0) ? index_plus_one : -index_plus_one;
189	  }
190	
191	  wgt_born() = src->wgt_born;
192	  wgt_ww_born() = src->wgt_ww_born;
193	  n_split() = src->n_split;
194	}
