196	void Particle::event_calculate_xs()
197	{
198	  // Set the random number stream
199	  stream() = STREAM_TRACKING;
200	
201	  // Store pre-collision particle properties
202	  wgt_last() = wgt();
203	  E_last() = E();
204	  u_last() = u();
205	  r_last() = r();
206	  time_last() = time();
207	
208	  // Reset event variables
209	  event() = TallyEvent::KILL;
210	  event_nuclide() = NUCLIDE_NONE;
211	  event_mt() = REACTION_NONE;
212	
213	  // If the cell hasn't been determined based on the particle's location,
214	  // initiate a search for the current cell. This generally happens at the
215	  // beginning of the history and again for any secondary particles
216	  if (lowest_coord().cell() == C_NONE) {
217	    if (!exhaustive_find_cell(*this)) {
218	      mark_as_lost(
219	        "Could not find the cell containing particle " + std::to_string(id()));
220	      return;
221	    }
222	
223	    // Set birth cell attribute
224	    if (cell_born() == C_NONE)
225	      cell_born() = lowest_coord().cell();
226	
227	    // Initialize last cells from current cell
228	    for (int j = 0; j < n_coord(); ++j) {
229	      cell_last(j) = coord(j).cell();
230	    }
231	    n_coord_last() = n_coord();
232	  }
233	
234	  // Write particle track.
235	  if (write_track())
236	    write_particle_track(*this);
237	
238	  if (settings::check_overlaps)
239	    check_cell_overlap(*this);
240	
241	  // Calculate microscopic and macroscopic cross sections
242	  if (material() != MATERIAL_VOID) {
243	    if (settings::run_CE) {
244	      if (material() != material_last() || sqrtkT() != sqrtkT_last() ||
245	          density_mult() != density_mult_last()) {
246	        // If the material is the same as the last material and the
247	        // temperature hasn't changed, we don't need to lookup cross
248	        // sections again.
249	        model::materials[material()]->calculate_xs(*this);
250	      }
251	    } else {
252	      // Get the MG data; unlike the CE case above, we have to re-calculate
253	      // cross sections for every collision since the cross sections may
254	      // be angle-dependent
255	      data::mg.macro_xs_[material()].calculate_xs(*this);
256	
257	      // Update the particle's group while we know we are multi-group
258	      g_last() = g();
259	    }
260	  } else {
261	    macro_xs().total = 0.0;
262	    macro_xs().absorption = 0.0;
263	    macro_xs().fission = 0.0;
264	    macro_xs().nu_fission = 0.0;
265	  }
266	}
