268	void Particle::event_advance()
269	{
270	  // Find the distance to the nearest boundary
271	  boundary() = distance_to_boundary(*this);
272	
273	  // Sample a distance to collision
274	  if (type() == ParticleType::electron() ||
275	      type() == ParticleType::positron()) {
276	    collision_distance() = material() == MATERIAL_VOID ? INFINITY : 0.0;
277	  } else if (macro_xs().total == 0.0) {
278	    collision_distance() = INFINITY;
279	  } else {
280	    collision_distance() = -std::log(prn(current_seed())) / macro_xs().total;
281	  }
282	
283	  double speed = this->speed();
284	  double time_cutoff = settings::time_cutoff[type().transport_index()];
285	  double distance_cutoff =
286	    (time_cutoff < INFTY) ? (time_cutoff - time()) * speed : INFTY;
287	
288	  // Select smaller of the three distances
289	  double distance =
290	    std::min({boundary().distance(), collision_distance(), distance_cutoff});
291	
292	  // Advance particle in space and time
293	  this->move_distance(distance);
294	  double dt = distance / speed;
295	  this->time() += dt;
296	  this->lifetime() += dt;
297	
298	  // Score timed track-length tallies
299	  if (!model::active_timed_tracklength_tallies.empty()) {
300	    score_timed_tracklength_tally(*this, distance);
301	  }
302	
303	  // Score track-length tallies
304	  if (!model::active_tracklength_tallies.empty()) {
305	    score_tracklength_tally(*this, distance);
306	  }
307	
308	  // Score track-length estimate of k-eff
309	  if (settings::run_mode == RunMode::EIGENVALUE && type().is_neutron()) {
310	    keff_tally_tracklength() += wgt() * distance * macro_xs().nu_fission;
311	  }
312	
313	  // Score flux derivative accumulators for differential tallies.
314	  if (!model::active_tallies.empty()) {
315	    score_track_derivative(*this, distance);
316	  }
317	
318	  // Set particle weight to zero if it hit the time boundary
319	  if (distance == distance_cutoff) {
320	    wgt() = 0.0;
321	  }
322	}
