324	void Particle::event_cross_surface()
325	{
326	  // Saving previous cell data
327	  for (int j = 0; j < n_coord(); ++j) {
328	    cell_last(j) = coord(j).cell();
329	  }
330	  n_coord_last() = n_coord();
331	
332	  // Set surface that particle is on and adjust coordinate levels
333	  surface() = boundary().surface();
334	  n_coord() = boundary().coord_level();
335	
336	  if (boundary().lattice_translation()[0] != 0 ||
337	      boundary().lattice_translation()[1] != 0 ||
338	      boundary().lattice_translation()[2] != 0) {
339	    // Particle crosses lattice boundary
340	
341	    bool verbose = settings::verbosity >= 10 || trace();
342	    cross_lattice(*this, boundary(), verbose);
343	    event() = TallyEvent::LATTICE;
344	
345	    // Score cell to cell partial currents
346	    if (!model::active_surface_tallies.empty()) {
347	      auto& lat {*model::lattices[lowest_coord().lattice()]};
348	      bool is_valid;
349	      Direction normal =
350	        lat.get_normal(boundary().lattice_translation(), is_valid);
351	      if (is_valid) {
352	        normal /= normal.norm();
353	        score_surface_tally(*this, model::active_surface_tallies, normal);
354	      }
355	    }
356	
357	  } else {
358	
359	    const auto& surf {*model::surfaces[surface_index()].get()};
360	
361	    // Particle crosses surface
362	    // If BC, add particle to surface source before crossing surface
363	    if (surf.surf_source_ && surf.bc_) {
364	      add_surf_source_to_bank(*this, surf);
365	    }
366	    this->cross_surface(surf);
367	    // If no BC, add particle to surface source after crossing surface
368	    if (surf.surf_source_ && !surf.bc_) {
369	      add_surf_source_to_bank(*this, surf);
370	    }
371	    if (settings::weight_window_checkpoint_surface) {
372	      apply_weight_windows(*this);
373	    }
374	    event() = TallyEvent::SURFACE;
375	
376	    // Score cell to cell partial currents
377	    if (!model::active_surface_tallies.empty()) {
378	      Direction normal = surf.normal(r());
379	      normal /= normal.norm();
380	      score_surface_tally(*this, model::active_surface_tallies, normal);
381	    }
382	  }
383	}
