385	void Particle::event_collide()
386	{
387	
388	  // Score collision estimate of keff
389	  if (settings::run_mode == RunMode::EIGENVALUE && type().is_neutron()) {
390	    keff_tally_collision() += wgt() * macro_xs().nu_fission / macro_xs().total;
391	  }
392	
393	  // Score surface current tallies -- this has to be done before the collision
394	  // since the direction of the particle will change and we need to use the
395	  // pre-collision direction to figure out what mesh surfaces were crossed
396	
397	  if (!model::active_meshsurf_tallies.empty())
398	    score_meshsurface_tally(*this, model::active_meshsurf_tallies);
399	
400	  // Clear surface component
401	  surface() = SURFACE_NONE;
402	
403	  if (settings::run_CE) {
404	    collision(*this);
405	  } else {
406	    collision_mg(*this);
407	  }
408	
409	  // Collision track feature to recording particle interaction
410	  if (settings::collision_track) {
411	    collision_track_record(*this);
412	  }
413	
414	  // Score collision estimator tallies -- this is done after a collision
415	  // has occurred rather than before because we need information on the
416	  // outgoing energy for any tallies with an outgoing energy filter
417	  if (!model::active_collision_tallies.empty())
418	    score_collision_tally(*this);
419	  if (!model::active_analog_tallies.empty()) {
420	    if (settings::run_CE) {
421	      score_analog_tally_ce(*this);
422	    } else {
423	      score_analog_tally_mg(*this);
424	    }
425	  }
426	
427	  if (!model::active_pulse_height_tallies.empty() && type().is_photon()) {
428	    pht_collision_energy();
429	  }
430	
431	  // Reset banked weight during collision
432	  n_bank() = 0;
433	  bank_second_E() = 0.0;
434	  wgt_bank() = 0.0;
435	
436	  // Clear number of secondaries in this collision. This is
437	  // distinct from the number of created neutrons n_bank() above!
438	  n_secondaries() = 0;
439	
440	  zero_delayed_bank();
441	
442	  // Reset fission logical
443	  fission() = false;
444	
445	  // Save coordinates for tallying purposes
446	  r_last_current() = r();
447	
448	  // Set last material to none since cross sections will need to be
449	  // re-evaluated
450	  material_last() = C_NONE;
451	
452	  // Set all directions to base level -- right now, after a collision, only
453	  // the base level directions are changed
454	  for (int j = 0; j < n_coord() - 1; ++j) {
455	    if (coord(j + 1).rotated()) {
456	      // If next level is rotated, apply rotation matrix
457	      const auto& m {model::cells[coord(j).cell()]->rotation_};
458	      const auto& u {coord(j).u()};
459	      coord(j + 1).u() = u.rotate(m);
460	    } else {
461	      // Otherwise, copy this level's direction
462	      coord(j + 1).u() = coord(j).u();
463	    }
464	  }
465	
466	  // Score flux derivative accumulators for differential tallies.
467	  if (!model::active_tallies.empty())
468	    score_collision_derivative(*this);
469	
470	#ifdef OPENMC_DAGMC_ENABLED
471	  history().reset();
472	#endif
473	}
