475	void Particle::event_revive_from_secondary(const SourceSite& site)
476	{
477	  // Write final position for the previous track (skip if this is a freshly
478	  // constructed particle with no prior track, e.g., Phase 2 of shared
479	  // secondary transport)
480	  if (write_track() && n_event() > 0) {
481	    write_particle_track(*this);
482	  }
483	
484	  from_source(&site);
485	
486	  n_event() = 0;
487	  if (!settings::use_shared_secondary_bank) {
488	    n_tracks()++;
489	  }
490	  bank_second_E() = 0.0;
491	
492	  // Subtract secondary particle energy from interim pulse-height results.
493	  // In shared secondary mode, this subtraction was already done on the parent
494	  // particle during create_secondary(), so skip it here.
495	  if (!settings::use_shared_secondary_bank &&
496	      !model::active_pulse_height_tallies.empty() && this->type().is_photon()) {
497	    // Since the birth cell of the particle has not been set we
498	    // have to determine it before the energy of the secondary particle can be
499	    // removed from the pulse-height of this cell.
500	    if (lowest_coord().cell() == C_NONE) {
501	      bool verbose = settings::verbosity >= 10 || trace();
502	      if (!exhaustive_find_cell(*this, verbose)) {
503	        mark_as_lost("Could not find the cell containing particle " +
504	                     std::to_string(id()));
505	        return;
506	      }
507	      // Set birth cell attribute
508	      if (cell_born() == C_NONE)
509	        cell_born() = lowest_coord().cell();
510	
511	      // Initialize last cells from current cell
512	      for (int j = 0; j < n_coord(); ++j) {
513	        cell_last(j) = coord(j).cell();
514	      }
515	      n_coord_last() = n_coord();
516	    }
517	    pht_secondary_particles();
518	  }
519	
520	  // Enter new particle in particle track file
521	  if (write_track())
522	    add_particle_track(*this);
523	}
