525	void Particle::event_check_limit_and_revive()
526	{
527	  // If particle has too many events, display warning and kill it
528	  n_event()++;
529	  if (n_event() == settings::max_particle_events) {
530	    warning("Particle " + std::to_string(id()) +
531	            " underwent maximum number of events.");
532	    wgt() = 0.0;
533	  }
534	
535	  // In non-shared-secondary mode, revive from local secondary bank
536	  if (!alive() && !settings::use_shared_secondary_bank &&
537	      !local_secondary_bank().empty()) {
538	    SourceSite& site = local_secondary_bank().back();
539	    event_revive_from_secondary(site);
540	    local_secondary_bank().pop_back();
541	  }
542	}
