544	void Particle::event_death()
545	{
546	#ifdef OPENMC_DAGMC_ENABLED
547	  history().reset();
548	#endif
549	
550	  // Finish particle track output.
551	  if (write_track()) {
552	    write_particle_track(*this);
553	    finalize_particle_track(*this);
554	  }
555	
556	// Contribute tally reduction variables to global accumulator
557	#pragma omp atomic
558	  global_tally_absorption += keff_tally_absorption();
559	#pragma omp atomic
560	  global_tally_collision += keff_tally_collision();
561	#pragma omp atomic
562	  global_tally_tracklength += keff_tally_tracklength();
563	#pragma omp atomic
564	  global_tally_leakage += keff_tally_leakage();
565	
566	  // Reset particle tallies once accumulated
567	  keff_tally_absorption() = 0.0;
568	  keff_tally_collision() = 0.0;
569	  keff_tally_tracklength() = 0.0;
570	  keff_tally_leakage() = 0.0;
571	
572	  if (!model::active_pulse_height_tallies.empty()) {
573	    score_pulse_height_tally(*this, model::active_pulse_height_tallies);
574	  }
575	
576	  // Accumulate track count for this particle history
577	  if (!settings::use_shared_secondary_bank) {
578	#pragma omp atomic
579	    simulation::simulation_tracks_completed += n_tracks();
580	  }
581	
582	  // Record the number of progeny created by this particle.
583	  // This data will be used to efficiently sort the fission bank.
584	  if (settings::run_mode == RunMode::EIGENVALUE ||
585	      settings::use_shared_secondary_bank) {
586	    simulation::progeny_per_particle[current_work()] = n_progeny();
587	  }
588	}
