590	void Particle::pht_collision_energy()
591	{
592	  // Adds the energy particles lose in a collision to the pulse-height
593	
594	  // determine index of cell in pulse_height_cells
595	  auto it = std::find(model::pulse_height_cells.begin(),
596	    model::pulse_height_cells.end(), lowest_coord().cell());
597	
598	  if (it != model::pulse_height_cells.end()) {
599	    int index = std::distance(model::pulse_height_cells.begin(), it);
600	    pht_storage()[index] += E_last() - E();
601	
602	    // If the energy of the particle is below the cutoff, it will not be sampled
603	    // so its energy is added to the pulse-height in the cell
604	    int photon = ParticleType::photon().transport_index();
605	    if (E() < settings::energy_cutoff[photon]) {
606	      pht_storage()[index] += E();
607	    }
608	  }
609	}
610	
611	void Particle::pht_secondary_particles()
612	{
613	  // Removes the energy of secondary produced particles from the pulse-height
614	
615	  // determine index of cell in pulse_height_cells
616	  auto it = std::find(model::pulse_height_cells.begin(),
617	    model::pulse_height_cells.end(), cell_born());
618	
619	  if (it != model::pulse_height_cells.end()) {
620	    int index = std::distance(model::pulse_height_cells.begin(), it);
621	    pht_storage()[index] -= E();
622	  }
623	}
