625	void Particle::cross_surface(const Surface& surf)
626	{
627	
628	  if (settings::verbosity >= 10 || trace()) {
629	    write_message(1, "    Crossing surface {}", surf.id_);
630	  }
631	
632	// if we're crossing a CSG surface, make sure the DAG history is reset
633	#ifdef OPENMC_DAGMC_ENABLED
634	  if (surf.geom_type() == GeometryType::CSG)
635	    history().reset();
636	#endif
637	
638	  // Handle any applicable boundary conditions.
