733	void Particle::cross_reflective_bc(const Surface& surf, Direction new_u)
734	{
735	  // Do not handle reflective boundary conditions on lower universes
736	  if (n_coord() != 1) {
737	    mark_as_lost("Cannot reflect particle " + std::to_string(id()) +
738	                 " off surface in a lower universe.");
739	    return;
740	  }
741	
742	  // Score surface currents since reflection causes the direction of the
743	  // particle to change. For surface filters, we need to score the tallies
744	  // twice, once before the particle's surface attribute has changed and
745	  // once after. For mesh surface filters, we need to artificially move
746	  // the particle slightly back in case the surface crossing is coincident
747	  // with a mesh boundary
748	
749	  if (!model::active_surface_tallies.empty()) {
750	    Direction normal = surf.normal(r());
751	    normal /= normal.norm();
752	    score_surface_tally(*this, model::active_surface_tallies, normal);
753	  }
754	
755	  if (!model::active_meshsurf_tallies.empty()) {
756	    Position r {this->r()};
757	    this->r() -= TINY_BIT * u();
758	    score_meshsurface_tally(*this, model::active_meshsurf_tallies);
759	    this->r() = r;
760	  }
761	
762	  // Set the new particle direction
763	  u() = new_u;
764	
765	  // Reassign particle's cell and surface
766	  coord(0).cell() = cell_last(0);
767	  surface() = -surface();
768	
769	  // If a reflective surface is coincident with a lattice or universe
770	  // boundary, it is necessary to redetermine the particle's coordinates in
771	  // the lower universes.
772	  // (unless we're using a dagmc model, which has exactly one universe)
773	  n_coord() = 1;
774	  if (surf.geom_type() != GeometryType::DAG &&
775	      !neighbor_list_find_cell(*this)) {
776	    mark_as_lost("Couldn't find particle after reflecting from surface " +
777	                 std::to_string(surf.id_) + ".");
778	    return;
779	  }
780	
781	  // Set previous coordinate going slightly past surface crossing
782	  r_last_current() = r() + TINY_BIT * u();
783	
784	  // Diagnostic message
785	  if (settings::verbosity >= 10 || trace()) {
786	    write_message(1, "    Reflected from surface {}", surf.id_);
787	  }
788	}
