123	void Cell::set_temperature(double T, int32_t instance, bool set_contained)
124	{
125	  if (settings::temperature_method == TemperatureMethod::INTERPOLATION) {
126	    if (T < (data::temperature_min - settings::temperature_tolerance)) {
127	      throw std::runtime_error {
128	        fmt::format("Temperature of {} K is below minimum temperature at "
129	                    "which data is available of {} K.",
130	          T, data::temperature_min)};
131	    } else if (T > (data::temperature_max + settings::temperature_tolerance)) {
132	      throw std::runtime_error {
133	        fmt::format("Temperature of {} K is above maximum temperature at "
134	                    "which data is available of {} K.",
135	          T, data::temperature_max)};
136	    }
137	  }
138	
139	  if (type_ == Fill::MATERIAL) {
140	    if (instance >= 0) {
141	      // If temperature vector is not big enough, resize it first
142	      if (sqrtkT_.size() != n_instances())
143	        sqrtkT_.resize(n_instances(), sqrtkT_[0]);
144	
145	      // Set temperature for the corresponding instance
146	      sqrtkT_.at(instance) = std::sqrt(K_BOLTZMANN * T);
147	    } else {
148	      // Set temperature for all instances
149	      for (auto& T_ : sqrtkT_) {
150	        T_ = std::sqrt(K_BOLTZMANN * T);
151	      }
152	    }
153	  } else {
154	    if (!set_contained) {
155	      throw std::runtime_error {
156	        fmt::format("Attempted to set the temperature of cell {} "
157	                    "which is not filled by a material.",
158	          id_)};
159	    }
160	
161	    auto contained_cells = this->get_contained_cells(instance);
162	    for (const auto& entry : contained_cells) {
163	      auto& cell = model::cells[entry.first];
164	      assert(cell->type_ == Fill::MATERIAL);
165	      auto& instances = entry.second;
166	      for (auto instance : instances) {
167	        cell->set_temperature(T, instance);
168	      }
169	    }
170	  }
171	}
