237	void Cell::import_properties_hdf5(hid_t group)
238	{
239	  auto cell_group = open_group(group, fmt::format("cell {}", id_));
240	
241	  // Read temperatures from file
242	  vector<double> temps;
243	  read_dataset(cell_group, "temperature", temps);
244	
245	  // Ensure number of temperatures makes sense
246	  auto n_temps = temps.size();
247	  if (n_temps > 1 && n_temps != n_instances()) {
248	    fatal_error(fmt::format(
249	      "Number of temperatures for cell {} doesn't match number of instances",
250	      id_));
251	  }
252	
253	  // Modify temperatures for the cell
254	  sqrtkT_.clear();
255	  sqrtkT_.resize(temps.size());
256	  for (int64_t i = 0; i < temps.size(); ++i) {
257	    this->set_temperature(temps[i], i);
258	  }
259	
260	  // Read densities
261	  if (object_exists(cell_group, "density")) {
262	    vector<double> density;
263	    read_dataset(cell_group, "density", density);
264	
265	    // Ensure number of densities makes sense
266	    auto n_density = density.size();
267	    if (n_density > 1 && n_density != n_instances()) {
268	      fatal_error(fmt::format("Number of densities for cell {} "
269	                              "doesn't match number of instances",
270	        id_));
271	    }
272	
273	    // Set densities.
274	    for (int32_t i = 0; i < n_density; ++i) {
275	      this->set_density(density[i], i);
276	    }
277	  }
278	
279	  close_group(cell_group);
