282	void Cell::to_hdf5(hid_t cell_group) const
283	{
284	
285	  // Create a group for this cell.
286	  auto group = create_group(cell_group, fmt::format("cell {}", id_));
287	
288	  if (!name_.empty()) {
289	    write_string(group, "name", name_, false);
290	  }
291	
292	  write_dataset(group, "universe", model::universes[universe_]->id_);
293	
294	  to_hdf5_inner(group);
295	
296	  // Write fill information.
297	  if (type_ == Fill::MATERIAL) {
298	    write_dataset(group, "fill_type", "material");
299	    std::vector<int32_t> mat_ids;
300	    for (auto i_mat : material_) {
301	      if (i_mat != MATERIAL_VOID) {
302	        mat_ids.push_back(model::materials[i_mat]->id_);
303	      } else {
304	        mat_ids.push_back(MATERIAL_VOID);
305	      }
306	    }
307	    if (mat_ids.size() == 1) {
308	      write_dataset(group, "material", mat_ids[0]);
309	    } else {
310	      write_dataset(group, "material", mat_ids);
311	    }
312	
313	    std::vector<double> temps;
314	    for (auto sqrtkT_val : sqrtkT_)
315	      temps.push_back(sqrtkT_val * sqrtkT_val / K_BOLTZMANN);
316	    write_dataset(group, "temperature", temps);
317	
318	    write_dataset(group, "density_mult", density_mult_);
319	
320	  } else if (type_ == Fill::UNIVERSE) {
321	    write_dataset(group, "fill_type", "universe");
322	    write_dataset(group, "fill", model::universes[fill_]->id_);
323	    if (translation_ != Position(0, 0, 0)) {
324	      write_dataset(group, "translation", translation_);
325	    }
326	    if (!rotation_.empty()) {
327	      if (rotation_.size() == 12) {
328	        std::array<double, 3> rot {rotation_[9], rotation_[10], rotation_[11]};
329	        write_dataset(group, "rotation", rot);
330	      } else {
331	        write_dataset(group, "rotation", rotation_);
332	      }
333	    }
334	
335	  } else if (type_ == Fill::LATTICE) {
336	    write_dataset(group, "fill_type", "lattice");
337	    write_dataset(group, "lattice", model::lattices[fill_]->id_);
338	  }
339	
340	  close_group(group);
341	}
