578	//==============================================================================
579	// Region implementation

580	//==============================================================================
581	
582	Region::Region(std::string region_spec, int32_t cell_id)
583	{
584	  // Check if region_spec is not empty.
585	  if (!region_spec.empty()) {
586	    // Parse all halfspaces and operators except for intersection (whitespace).
587	    for (int i = 0; i < region_spec.size();) {
588	      if (region_spec[i] == '(') {
589	        expression_.push_back(OP_LEFT_PAREN);
590	        i++;
591	
592	      } else if (region_spec[i] == ')') {
593	        expression_.push_back(OP_RIGHT_PAREN);
594	        i++;
595	
596	      } else if (region_spec[i] == '|') {
597	        expression_.push_back(OP_UNION);
598	        i++;
599	
600	      } else if (region_spec[i] == '~') {
601	        expression_.push_back(OP_COMPLEMENT);
602	        i++;
603	
604	      } else if (region_spec[i] == '-' || region_spec[i] == '+' ||
605	                 std::isdigit(region_spec[i])) {
606	        // This is the start of a halfspace specification.  Iterate j until we
607	        // find the end, then push-back everything between i and j.
608	        int j = i + 1;
609	        while (j < region_spec.size() && std::isdigit(region_spec[j])) {
610	          j++;
611	        }
612	        expression_.push_back(std::stoi(region_spec.substr(i, j - i)));
613	        i = j;
614	
615	      } else if (std::isspace(region_spec[i])) {
616	        i++;
617	
618	      } else {
619	        auto err_msg =
620	          fmt::format("Region specification contains invalid character, \"{}\"",
621	            region_spec[i]);
622	        fatal_error(err_msg);
623	      }
624	    }
625	
626	    // Add in intersection operators where a missing operator is needed.
627	    int i = 0;
628	    while (i < expression_.size() - 1) {
629	      bool left_compat {
630	        (expression_[i] < OP_UNION) || (expression_[i] == OP_RIGHT_PAREN)};
631	      bool right_compat {(expression_[i + 1] < OP_UNION) ||
632	                         (expression_[i + 1] == OP_LEFT_PAREN) ||
633	                         (expression_[i + 1] == OP_COMPLEMENT)};
634	      if (left_compat && right_compat) {
635	        expression_.insert(expression_.begin() + i + 1, OP_INTERSECTION);
636	      }
637	      i++;
638	    }
639	
640	    // Remove complement operators using DeMorgan's laws
641	    auto it = std::find(expression_.begin(), expression_.end(), OP_COMPLEMENT);
642	    while (it != expression_.end()) {
643	      // Erase complement
644	      expression_.erase(it);
645	
646	      // Define stop given left parenthesis or not
647	      auto stop = it;
648	      if (*it == OP_LEFT_PAREN) {
649	        int depth = 1;
650	        do {
651	          stop++;
652	          if (*stop > OP_COMPLEMENT) {
653	            if (*stop == OP_RIGHT_PAREN) {
654	              depth--;
655	            } else {
656	              depth++;
657	            }
658	          }
659	        } while (depth > 0);
660	        it++;
661	      }
662	
663	      // apply DeMorgan's law to any surfaces/operators between these
664	      // positions in the RPN
665	      apply_demorgan(it, stop);
666	      // update iterator position
667	      it = std::find(expression_.begin(), expression_.end(), OP_COMPLEMENT);
668	    }
669	
670	    // Convert user IDs to surface indices.
671	    for (auto& r : expression_) {
672	      if (r < OP_UNION) {
673	        const auto& it {model::surface_map.find(abs(r))};
674	        if (it == model::surface_map.end()) {
675	          throw std::runtime_error {
676	            "Invalid surface ID " + std::to_string(abs(r)) +
677	            " specified in region for cell " + std::to_string(cell_id) + "."};
678	        }
679	        r = (r > 0) ? it->second + 1 : -(it->second + 1);
680	      }
681	    }
682	
683	    // Check if this is a simple cell.
684	    simple_ = true;
685	    for (int32_t token : expression_) {
686	      if (token == OP_UNION) {
687	        simple_ = false;
688	        // Ensure intersections have precedence over unions
689	        enforce_precedence();
690	        break;
691	      }
692	    }
693	
694	    // If this cell is simple, remove all the superfluous operator tokens.
695	    if (simple_) {
696	      for (auto it = expression_.begin(); it != expression_.end(); it++) {
697	        if (*it == OP_INTERSECTION || *it > OP_COMPLEMENT) {
698	          expression_.erase(it);
699	          it--;
700	        }
701	      }
702	    }
703	    expression_.shrink_to_fit();
704	
705	  } else {
706	    simple_ = true;
707	  }
708	}
