727	//==============================================================================
728	//! Add precedence for infix regions so intersections have higher
729	//! precedence than unions using parentheses.
730	//==============================================================================
731	
732	void Region::add_parentheses(int64_t start)
733	{
734	  int32_t start_token = expression_[start];
735	  // Add left parenthesis and set new position to be after parenthesis
736	  if (start_token == OP_UNION) {
737	    start += 2;
738	  }
739	  expression_.insert(expression_.begin() + start - 1, OP_LEFT_PAREN);
740	
741	  // Add right parenthesis
742	  // While the start iterator is within the bounds of infix
743	  while (start + 1 < expression_.size()) {
744	    start++;
745	
746	    // If the current token is an operator and is different than the start token
747	    if (expression_[start] >= OP_UNION && expression_[start] != start_token) {
748	      // Skip wrapped regions but save iterator position to check precedence and
749	      // add right parenthesis, right parenthesis position depends on the
750	      // operator, when the operator is a union then do not include the operator
751	      // in the region, when the operator is an intersection then include the
752	      // operator and next surface
753	      if (expression_[start] == OP_LEFT_PAREN) {
754	        int depth = 1;
755	        do {
756	          start++;
757	          if (expression_[start] > OP_COMPLEMENT) {
758	            if (expression_[start] == OP_RIGHT_PAREN) {
759	              depth--;
760	            } else {
761	              depth++;
762	            }
763	          }
764	        } while (depth > 0);
765	      } else {
766	        if (start_token == OP_UNION) {
767	          --start;
768	        }
769	        expression_.insert(expression_.begin() + start, OP_RIGHT_PAREN);
770	        return;
771	      }
772	    }
773	  }
774	  // If we get here a right parenthesis hasn't been placed
775	  expression_.push_back(OP_RIGHT_PAREN);
776	}
777	
778	//==============================================================================
779	//! Add parentheses to enforce operator precedence in region expressions
780	//!
781	//! This function ensures that intersection operators have higher precedence
782	//! than union operators by adding parentheses where needed. For example:
783	//!   "1 2 | 3" becomes "(1 2) | 3"
784	//!   "1 | 2 3" becomes "1 | (2 3)"
785	//!
786	//! The algorithm uses stacks to track the current operator type and its
787	//! position at each parenthesis depth level. When it encounters a different
788	//! operator at the same depth, it adds parentheses to group the
789	//! higher-precedence operations.
790	//==============================================================================
791	
792	void Region::enforce_precedence()
793	{
794	  // Stack tracking the operator type at each depth (0 = no operator seen yet)
795	  vector<int32_t> op_stack = {0};
796	
797	  // Stack tracking where the operator sequence started at each depth
798	  vector<std::size_t> pos_stack = {0};
799	
800	  for (int64_t i = 0; i < expression_.size(); ++i) {
801	    int32_t token = expression_[i];
802	
803	    if (token == OP_LEFT_PAREN) {
804	      // Entering a new parenthesis level - push new tracking state
805	      op_stack.push_back(0);
806	      pos_stack.push_back(0);
807	      continue;
808	    } else if (token == OP_RIGHT_PAREN) {
809	      // Exiting a parenthesis level - pop tracking state (keep at least one)
810	      if (op_stack.size() > 1) {
811	        op_stack.pop_back();
812	        pos_stack.pop_back();
813	      }
814	      continue;
815	    }
816	
817	    if (token == OP_UNION || token == OP_INTERSECTION) {
818	      if (op_stack.back() == 0) {
819	        // First operator at this depth - record it and its position
820	        op_stack.back() = token;
821	        pos_stack.back() = i;
822	      } else if (token != op_stack.back()) {
823	        // Encountered a different operator at the same depth - need to add
824	        // parentheses to enforce precedence. Intersection has higher
825	        // precedence, so we parenthesize the intersection terms.
826	        if (op_stack.back() == OP_INTERSECTION) {
827	          add_parentheses(pos_stack.back());
828	        } else {
829	          add_parentheses(i);
830	        }
831	
832	        // Restart the scan since we modified the expression
833	        i = -1; // Will be incremented to 0 by the for loop
834	        op_stack = {0};
835	        pos_stack = {0};
836	      }
837	    }
838	  }
839	}
840	
841	//==============================================================================
842	//! Convert infix region specification to Reverse Polish Notation (RPN)
843	//!
844	//! This function uses the shunting-yard algorithm.
845	//==============================================================================
846	
847	vector<int32_t> Region::generate_postfix(int32_t cell_id) const
848	{
849	  vector<int32_t> rpn;
850	  vector<int32_t> stack;
851	
852	  for (int32_t token : expression_) {
853	    if (token < OP_UNION) {
854	      // If token is not an operator, add it to output
855	      rpn.push_back(token);
856	    } else if (token < OP_RIGHT_PAREN) {
857	      // Regular operators union, intersection, complement
858	      while (stack.size() > 0) {
859	        int32_t op = stack.back();
860	
861	        if (op < OP_RIGHT_PAREN && ((token == OP_COMPLEMENT && token < op) ||
862	                                     (token != OP_COMPLEMENT && token <= op))) {
863	          // While there is an operator, op, on top of the stack, if the token
864	          // is left-associative and its precedence is less than or equal to
865	          // that of op or if the token is right-associative and its precedence
866	          // is less than that of op, move op to the output queue and push the
867	          // token on to the stack. Note that only complement is
868	          // right-associative.
869	          rpn.push_back(op);
870	          stack.pop_back();
871	        } else {
872	          break;
873	        }
874	      }
875	
876	      stack.push_back(token);
877	
878	    } else if (token == OP_LEFT_PAREN) {
879	      // If the token is a left parenthesis, push it onto the stack
880	      stack.push_back(token);
881	
882	    } else {
883	      // If the token is a right parenthesis, move operators from the stack to
884	      // the output queue until reaching the left parenthesis.
885	      for (auto it = stack.rbegin(); *it != OP_LEFT_PAREN; it++) {
886	        // If we run out of operators without finding a left parenthesis, it
887	        // means there are mismatched parentheses.
888	        if (it == stack.rend()) {
889	          fatal_error(fmt::format(
890	            "Mismatched parentheses in region specification for cell {}",
891	            cell_id));
892	        }
893	        rpn.push_back(stack.back());
894	        stack.pop_back();
895	      }
896	
897	      // Pop the left parenthesis.
898	      stack.pop_back();
899	    }
900	  }
901	
902	  while (stack.size() > 0) {
903	    int32_t op = stack.back();
904	
905	    // If the operator is a parenthesis it is mismatched.
906	    if (op >= OP_RIGHT_PAREN) {
907	      fatal_error(fmt::format(
908	        "Mismatched parentheses in region specification for cell {}", cell_id));
909	    }
910	
911	    rpn.push_back(stack.back());
912	    stack.pop_back();
913	  }
914	
915	  return rpn;
916	}
