919	
920	std::string Region::str() const
921	{
922	  std::stringstream region_spec {};
923	  if (!expression_.empty()) {
924	    for (int32_t token : expression_) {
925	      if (token == OP_LEFT_PAREN) {
926	        region_spec << " (";
927	      } else if (token == OP_RIGHT_PAREN) {
928	        region_spec << " )";
929	      } else if (token == OP_COMPLEMENT) {
930	        region_spec << " ~";
931	      } else if (token == OP_INTERSECTION) {
932	      } else if (token == OP_UNION) {
933	        region_spec << " |";
934	      } else {
935	        // Note the off-by-one indexing
936	        auto surf_id = model::surfaces[abs(token) - 1]->id_;
937	        region_spec << " " << ((token > 0) ? surf_id : -surf_id);
938	      }
939	    }
940	  }
941	  return region_spec.str();
942	}
