944	//==============================================================================
945	
946	std::pair<double, int32_t> Region::distance(
947	  Position r, Direction u, int32_t on_surface) const
948	{
949	  double min_dist {INFTY};
950	  int32_t i_surf {std::numeric_limits<int32_t>::max()};
951	
952	  for (int32_t token : expression_) {
953	    // Ignore this token if it corresponds to an operator rather than a region.
954	    if (token >= OP_UNION)
955	      continue;
956	
957	    // Calculate the distance to this surface.
958	    // Note the off-by-one indexing
959	    bool coincident {std::abs(token) == std::abs(on_surface)};
960	    double d {model::surfaces[abs(token) - 1]->distance(r, u, coincident)};
961	
962	    // Check if this distance is the new minimum.
963	    if (d < min_dist) {
964	      if (min_dist - d >= FP_PRECISION * min_dist) {
965	        min_dist = d;
966	        i_surf = -token;
967	      }
968	    }
969	  }
970	
971	  return {min_dist, i_surf};
972	}
