985	//==============================================================================
986	
987	bool Region::contains_simple(Position r, Direction u, int32_t on_surface) const
988	{
989	  for (int32_t token : expression_) {
990	    // Assume that no tokens are operators. Evaluate the sense of particle with
991	    // respect to the surface and see if the token matches the sense. If the
992	    // particle's surface attribute is set and matches the token, that
993	    // overrides the determination based on sense().
994	    if (token == on_surface) {
995	    } else if (-token == on_surface) {
996	      return false;
997	    } else {
998	      // Note the off-by-one indexing
999	      bool sense = model::surfaces[abs(token) - 1]->sense(r, u);
1000	      if (sense != (token > 0)) {
1001	        return false;
1002	      }
1003	    }
1004	  }
1005	  return true;
1006	}
1007	
1008	//==============================================================================
1009	
1010	bool Region::contains_complex(Position r, Direction u, int32_t on_surface) const
1011	{
1012	  bool in_cell = true;
1013	  int total_depth = 0;
1014	
1015	  // For each token
1016	  for (auto it = expression_.begin(); it != expression_.end(); it++) {
1017	    int32_t token = *it;
1018	
1019	    // If the token is a surface evaluate the sense
1020	    // If the token is a union or intersection check to
1021	    // short circuit
1022	    if (token < OP_UNION) {
1023	      if (token == on_surface) {
1024	        in_cell = true;
1025	      } else if (-token == on_surface) {
1026	        in_cell = false;
1027	      } else {
1028	        // Note the off-by-one indexing
1029	        bool sense = model::surfaces[abs(token) - 1]->sense(r, u);
1030	        in_cell = (sense == (token > 0));
1031	      }
1032	    } else if ((token == OP_UNION && in_cell == true) ||
1033	               (token == OP_INTERSECTION && in_cell == false)) {
1034	      // If the total depth is zero return
1035	      if (total_depth == 0) {
1036	        return in_cell;
1037	      }
1038	
1039	      total_depth--;
1040	
1041	      // While the iterator is within the bounds of the vector
1042	      int depth = 1;
1043	      do {
1044	        // Get next token
1045	        it++;
1046	        int32_t next_token = *it;
1047	
1048	        // If the token is an a parenthesis
1049	        if (next_token > OP_COMPLEMENT) {
1050	          // Adjust depth accordingly
1051	          if (next_token == OP_RIGHT_PAREN) {
1052	            depth--;
1053	          } else {
1054	            depth++;
1055	          }
1056	        }
1057	      } while (depth > 0);
1058	    } else if (token == OP_LEFT_PAREN) {
1059	      total_depth++;
1060	    } else if (token == OP_RIGHT_PAREN) {
1061	      total_depth--;
1062	    }
1063	  }
1064	  return in_cell;
1065	}
