1068	
1069	BoundingBox Region::bounding_box(int32_t cell_id) const
1070	{
1071	  if (simple_) {
1072	    return bounding_box_simple();
1073	  } else {
1074	    auto postfix = generate_postfix(cell_id);
1075	    return bounding_box_complex(postfix);
1076	  }
