#include <cstdio>
#include <cmath>
#include <algorithm>
static const double FP_PRECISION = 1e-14;
// Simulate the residual round-trip error for various pitches.
// d = (x0-x)/u.x ; residual = |x + u.x*d - x0|  (exact in reals = 0)
static double residual(double pitch, double x, double ux){
  double x0 = copysign(0.5*pitch, ux);
  double d  = (x0 - x)/ux;          // this is the min (x gives the min)
  return std::abs(x + ux*d - x0);
}
int main(){
  printf("pitch   half   residual(round-trip)   <1e-14(abs tol) ?\n");
  double pitches[] = {10.0, 50.0, 100.0, 500.0, 1000.0, 1e4, 1e5, 1e6};
  for(double p: pitches){
    double r = residual(p, 0.0, 0.3602493); // x at tile center, moving
    printf("%-7g %-6g  %.3e            %s\n", p, 0.5*p, r, r<FP_PRECISION?"PASS":"FAIL(>tol)");
  }
  return 0;
}
