#include <cstdio>
#include <cmath>
#include <algorithm>
#include <random>
static const double FP_PRECISION = 1e-14;
// Replicate RectLattice::distance rounding: compute d then the two residuals
int main(){
  std::mt19937 gen(12345);
  std::uniform_real_distribution<double> urnd(-1.0,1.0);
  for (double pitch : {50.0, 500.0, 1000.0, 1e4, 1e5, 1e6}){
    double maxres=0, sumres=0; int n=0, failed=0;
    for(int t=0;t<200000;t++){
      // random off-center local position inside tile
      double x = (urnd(gen)-0.5)*pitch; // -0.5p..0.5p
      double y = (urnd(gen)-0.5)*pitch;
      double ux = urnd(gen), uy = urnd(gen);
      if (std::abs(ux)<1e-9) ux=0.3;
      if (std::abs(uy)<1e-9) uy=-0.4;
      double nx=std::hypot(ux,uy); ux/=nx; uy/=nx;
      double x0 = copysign(0.5*pitch, ux);
      double y0 = copysign(0.5*pitch, uy);
      double d  = std::min(ux!=0?(x0-x)/ux:1e300, uy!=0?(y0-y)/uy:1e300);
      // the oncoming axis is whichever gave the min; check its residual
      double dx = ux!=0?(x0-x)/ux:1e300;
      double dy = uy!=0?(y0-y)/uy:1e300;
      double res = (dx<dy)? std::abs(x+ux*d-x0) : std::abs(y+uy*d-y0);
      maxres=std::max(maxres,res); sumres+=res; n++;
      if(!(res<FP_PRECISION)) failed++;
    }
    printf("pitch=%-8g  max_resid=%-9.3e  mean=%-9.3e  frac_exceeding_1e-14=%6.4f%%\n",
      pitch, maxres, sumres/n, 100.0*failed/n);
  }
  return 0;
}
