// Determine the oncoming edge.
double x0 {copysign(0.5 * pitch_[0], u.x)};
double y0 {copysign(0.5 * pitch_[1], u.y)};
double z0;

// Candidate forward distances to each oncoming lattice edge (INFTY when the
// particle is not moving along that axis).  d is the nearest of them.
double dx {u.x != 0.0 ? (x0 - x) / u.x : INFTY};
double dy {u.y != 0.0 ? (y0 - y) / u.y : INFTY};
double d = std::min(dx, dy);
double dz {INFTY};
if (is_3d_) {
  z0 = copysign(0.5 * pitch_[2], u.z);
  dz = u.z != 0.0 ? (z0 - z) / u.z : INFTY;
  d = std::min(d, dz);
}

// Determine which lattice boundaries are being crossed.  An edge is oncoming
// when its candidate distance matches the selected minimum distance d.  Each
// axis is tested independently so that a particle crossing the corner (or
// edge) of several tiles is registered on all of them.  The comparison uses a
// relative tolerance: the historical test re-derived the crossing from the
// floating-point round-trip residual (x + u.x*d - x0), which is exactly zero
// in exact arithmetic but whose rounding error grows with the magnitude of the
// model coordinates.  A fixed absolute tolerance (FP_PRECISION) therefore
// misclassifies boundary crossings for large or small geometries, leaving the
// lattice translation unset while d is finite and producing an inconsistent
// boundary state.  Comparing the oncoming distances directly with a relative
// tolerance is invariant to the coordinate scale.
array<int, 3> lattice_trans = {0, 0, 0};
if (u.x != 0.0 &&
    std::abs(dx - d) <= FP_REL_PRECISION * std::max(std::abs(dx), std::abs(d)))
  lattice_trans[0] = copysign(1, u.x);
if (u.y != 0.0 &&
    std::abs(dy - d) <= FP_REL_PRECISION * std::max(std::abs(dy), std::abs(d)))
  lattice_trans[1] = copysign(1, u.y);
if (is_3d_) {
  if (u.z != 0.0 &&
      std::abs(dz - d) <=
        FP_REL_PRECISION * std::max(std::abs(dz), std::abs(d)))
    lattice_trans[2] = copysign(1, u.z);
}

return {d, lattice_trans};
